"""Small groups generated by two elements of order 3 (quotients of C3*C3), plus a few others.
Each entry: name -> (Group, a, b) with a, b element indices of order 3 (or small order)."""
import itertools
import numpy as np
from gmr import Group


def perm(cycles, d):
    p = list(range(d))
    for c in cycles:
        for i in range(len(c)):
            p[c[i]] = c[(i + 1) % len(c)]
    return p


class MatGroup(Group):
    """Group generated by 2x2 matrices mod q, stored as permutation-like objects via closure."""
    def __init__(self, gens, q):
        def mul(X, Y):
            return tuple(sum(X[2*i+k] * Y[2*k+j] for k in range(2)) % q for i in range(2) for j in range(2))
        e = (1, 0, 0, 1)
        elems = [e]; index = {e: 0}; frontier = [e]
        while frontier:
            nxt = []
            for x in frontier:
                for g in gens:
                    y = mul(g, x)
                    if y not in index:
                        index[y] = len(elems); elems.append(y); nxt.append(y)
            frontier = nxt
        self.elems, self.index = elems, index
        n = len(elems)
        self.mult = np.array([[index[mul(p, r)] for r in elems] for p in elems], dtype=np.int32)
        self.order = n
        self.inv = np.array([int(np.nonzero(self.mult[i] == 0)[0][0]) for i in range(n)])

    def el(self, M):
        return self.index[tuple(M)]


class Quotient:
    """G / Z for a normal subgroup Z (index list)."""
    def __init__(self, G, Z):
        Zs = set(Z)
        coset = -np.ones(G.order, dtype=np.int64); reps = []
        for g in range(G.order):
            if coset[g] < 0:
                c = len(reps); reps.append(g)
                for z in Z:
                    coset[G.mult[g, z]] = c
        self.coset = coset
        self.order = len(reps)
        self.mult = np.array([[coset[G.mult[r, s]] for s in reps] for r in reps], dtype=np.int32)
        self.inv = np.array([int(np.nonzero(self.mult[i] == 0)[0][0]) for i in range(self.order)])
        assert coset[0] == 0


def order_of(G, g):
    k, x = 1, g
    while x != 0:
        x = G.mult[x, g]; k += 1
    return k


def center(G):
    return [z for z in range(G.order) if np.array_equal(G.mult[z], G.mult[:, z])]


def gen_closure(G, gens):
    S = {0}; frontier = [0]
    while frontier:
        nxt = []
        for x in frontier:
            for g in gens:
                y = int(G.mult[x, g])
                if y not in S:
                    S.add(y); nxt.append(y)
        frontier = nxt
    return S


def order3_generating_pairs(G, limit=6, seed=0):
    """a few pairs (a,b) of order-3 elements generating G, up to simple duplicates"""
    import random
    rng = random.Random(seed)
    o3 = [g for g in range(G.order) if order_of(G, g) == 3]
    pairs = []
    tries = 0
    while len(pairs) < limit and tries < 5000:
        tries += 1
        a, b = rng.sample(o3, 2)
        if len(gen_closure(G, [a, b])) == G.order:
            pairs.append((a, b))
    return pairs


def build_all():
    out = {}
    # A4 (12) and A5 (60)
    A4 = Group([perm([(0, 1, 2)], 4), perm([(1, 2, 3)], 4)]); out["A4"] = A4
    A5 = Group([perm([(0, 1, 2)], 5), perm([(2, 3, 4)], 5)]); out["A5"] = A5
    # PSL(2,7) (168) on 7 points
    P = Group([perm([(0, 1, 2, 3, 4, 5, 6)], 7), perm([(0, 1), (2, 5)], 7)]); assert P.order == 168; out["PSL(2,7)"] = P
    # SL(2,3) (24) and C3 x SL(2,3) (72, from the paper), SL(2,5) (120)
    out["C3xSL(2,3)"] = MatGroup([(5, 5, 5, 1), (6, 5, 5, 6)], 7)
    out["SL(2,3)"] = MatGroup([(1, 1, 0, 1), (1, 0, 1, 1)], 3)
    out["SL(2,5)"] = MatGroup([(1, 1, 0, 1), (1, 0, 1, 1)], 5)
    # C3 wr C3 (81)
    out["C3wrC3"] = Group([perm([(0, 1, 2)], 9), perm([(0, 3, 6), (1, 4, 7), (2, 5, 8)], 9)])
    # SmallGroup(243,3) and its quotients by central subgroups of order 3 (order 81) and 9 (27)
    d = 18
    G243 = Group([perm([(6, 7, 8), (9, 15, 12), (10, 16, 13), (11, 17, 14)], d),
                  perm([(0, 3, 6), (1, 4, 7), (2, 5, 8), (15, 16, 17)], d)])
    out["SG(243,3)"] = G243
    Z = center(G243)
    seen = set()
    for z in Z:
        if z == 0 or order_of(G243, z) != 3: continue
        sub = tuple(sorted({0, z, int(G243.mult[z, z])}))
        if sub in seen: continue
        seen.add(sub)
        out[f"SG243/<z{len(seen)}> (81)"] = Quotient(G243, list(sub))
    out["SG243/Z (order %d)" % (243 // len(Z))] = Quotient(G243, Z)
    # A4 x C3 (36)
    out["A4xC3"] = Group([perm([(0, 1, 2), (4, 5, 6)], 7), perm([(1, 2, 3)], 7)])
    return out


if __name__ == "__main__":
    for k, G in build_all().items():
        print(k, G.order)
